//! Offscreen renders: the Build window's building thumbnails and the map
//! picture saved with a named game.
//!
//! Thumbnails: once, a few frames after startup, every placeable's building
//! is generated by the procgen grammar (`generate_building`, the same call
//! the city is drawn with) on a made-up lot, spawned far from the city on
//! its own render layer with its own key light, and filmed by an
//! orthographic camera into a small image. The cameras stay a couple of
//! seconds (the first frames of a new view may still be compiling
//! pipelines), then go with the meshes; the images stay, registered as egui
//! textures in [`Thumbs`].
//!
//! Save pictures: a top-down orthographic camera over the built-up area
//! renders into an image for a few frames, then a `Screenshot` of that
//! image is written next to the save (`saves/<name>.png`).

use std::collections::HashMap;
use std::path::PathBuf;

use bevy::camera::visibility::RenderLayers;
use bevy::camera::{RenderTarget, ScalingMode};
use bevy::light::{NotShadowCaster, NotShadowReceiver};
use bevy::prelude::*;
use bevy::render::render_resource::TextureFormat;
use bevy::render::view::screenshot::{save_to_disk, Screenshot};
use bevy_egui::{egui, EguiTextureHandle, EguiUserTextures};
use nd_procgen::{generate_building, Extras, Geometry};
use nd_sim::roads::{NodeId, SegmentId};
use nd_sim::{LandUse, Lot, Placeable, ServiceKind, Tier, Vec2 as SVec2};

use super::{to_mesh, Materials};
use crate::assets::GameAssets;
use crate::sim::Sim;

/// The render layer the thumbnail sets live on: no other camera sees it,
/// and the main lights do not light it.
const LAYER: usize = 7;
/// Thumbnail size in pixels (shown at 96 points, so sharp on high-DPI).
const SIZE: u32 = 192;
/// Frames the thumbnail cameras run before they are taken down.
const THUMB_FRAMES: u32 = 150;
/// Frames the save camera runs before its picture is taken.
const SHOT_FRAMES: u32 = 20;
/// Save picture size in pixels.
const SHOT_SIZE: u32 = 512;
/// Where the thumbnail sets stand: far outside the map, one per 2 km.
const ORIGIN: Vec3 = Vec3::new(60_000.0, 0.0, 60_000.0);

/// The rendered thumbnails, by placeable (services at their middle tier).
#[derive(Resource, Default)]
pub struct Thumbs {
    ids: HashMap<String, egui::TextureId>,
    /// Registered but still rendering.
    pending: HashMap<String, egui::TextureId>,
    temp: Vec<Entity>,
    frames: u32,
    started: bool,
}

impl Thumbs {
    pub fn get(&self, p: Placeable) -> Option<egui::TextureId> {
        self.ids.get(&key(p)).copied()
    }
}

fn key(p: Placeable) -> String {
    format!("{:?}", p.with_tier(Tier::Mid))
}

/// A save picture in the making.
struct Shot {
    path: PathBuf,
    camera: Entity,
    image: Handle<Image>,
    frames: u32,
}

/// Save pictures in flight (`ui::Saves` queues them).
#[derive(Resource, Default)]
pub struct SaveShots {
    running: Vec<Shot>,
}

pub struct ThumbsPlugin;

impl Plugin for ThumbsPlugin {
    fn build(&self, app: &mut App) {
        app.init_resource::<Thumbs>().init_resource::<SaveShots>().add_systems(Update, (make_thumbs, save_shots));
    }
}

/// A rectangular lot of `w` by `d` metres centred on the origin, fronting
/// a street along its south edge.
fn lot(w: f32, d: f32, land_use: LandUse) -> Lot {
    let (hw, hd) = (w * 0.5, d * 0.5);
    let c = [SVec2::new(-hw, -hd), SVec2::new(hw, -hd), SVec2::new(hw, hd), SVec2::new(-hw, hd)];
    Lot {
        zone: Default::default(),
        land_use,
        polygon: c.to_vec(),
        corners: c,
        front_edge: [c[0], c[1]],
        center: SVec2::ZERO,
        front_dir: SVec2::new(0.0, -1.0),
        front_segment: SegmentId(0),
        front_t: 0.5,
        access_node: NodeId(0),
        building: None,
        landlocked: false,
        footfall_today: 0,
        footfall_hour: 0,
        car_segment: Some(SegmentId(0)),
        car_point: SVec2::new(0.0, -hd - 3.0),
        park: None,
        shore: Default::default(),
    }
}

/// Floors a placed service stands at, middle tier (as the sim builds it).
fn service_floors(k: ServiceKind) -> u8 {
    match k {
        ServiceKind::Health => 4,
        ServiceKind::Monument | ServiceKind::TrashDepot | ServiceKind::ParkingEnforcement => 1,
        _ => 2,
    }
}

/// The building a placeable puts down, generated on a lot of its size.
/// None for things that are not buildings (toll booths).
#[allow(unreachable_patterns)]
fn building(p: Placeable, rules: &nd_procgen::BuildingRules, palette: &nd_procgen::Palette) -> Option<Geometry> {
    let side = |area: f32| {
        let a = area.max(600.0) * 1.15;
        (a.sqrt() * 1.1, a.sqrt() / 1.1)
    };
    let rail_link;
    let mut extras = Extras { powered: 1.0, ..Extras::default() };
    let (w, d, lu, floors) = match p {
        Placeable::Toll(_) => return None,
        Placeable::Plant(k) => {
            extras.plant = Some(k);
            let (w, d) = side(k.min_area());
            (w, d, LandUse::Industrial, 1)
        }
        Placeable::Service(k, t) => {
            extras.service = Some(k);
            let (w, d) = side(k.min_area(t));
            (w, d, LandUse::Civic, service_floors(k))
        }
        Placeable::BusDepot => {
            extras.depot = true;
            let (w, d) = side(p.min_area());
            (w, d, LandUse::Industrial, 1)
        }
        Placeable::Rail(f) => {
            let (w, d) = nd_sim::Facility::size(f);
            rail_link = nd_sim::rail::RailLink { kind: f, segment: SegmentId(0), platform: [SVec2::new(-w * 0.5, d * 0.5 + 2.0), SVec2::new(w * 0.5, d * 0.5 + 2.0)], side: 1.0, rail_connected: true, road_connected: true };
            extras.rail = Some(&rail_link);
            (w, d, LandUse::Industrial, 1)
        }
        Placeable::Dock(k) => {
            extras.port = Some(k);
            let (w, d) = k.size();
            (w, d, LandUse::Industrial, 1)
        }
        Placeable::ParkingLot(s) => {
            extras.parking = Some(0.6);
            let (w, d) = side(s.min_area());
            (w, d, LandUse::Commercial, s.floors())
        }
        Placeable::MetroStation => {
            extras.metro = true;
            let (w, d) = side(p.min_area());
            (w, d, LandUse::Civic, 1)
        }
        Placeable::CargoHub => {
            extras.business = Some(nd_sim::BusinessKind::CargoHub);
            let (w, d) = side(p.min_area());
            (w, d, LandUse::Industrial, 1)
        }
        // Anything newer: drawn as the land use's ordinary building.
        _ => {
            let (w, d) = side(p.min_area());
            (w, d, LandUse::Industrial, 2)
        }
    };
    let lot = lot(w, d, lu);
    let seed = 0x7EED_0000 ^ key(p).bytes().fold(0u64, |h, b| h.wrapping_mul(31).wrapping_add(b as u64));
    Some(generate_building(&lot, lu, floors, Tier::Mid, 1.0, seed, rules, palette, &extras))
}

/// Bounds of a geometry's vertices.
fn bounds(g: &Geometry) -> Option<(Vec3, Vec3)> {
    let mut lo = Vec3::splat(f32::MAX);
    let mut hi = Vec3::splat(f32::MIN);
    for (_, m) in g.iter() {
        for p in &m.positions {
            let v = Vec3::from_array(*p);
            lo = lo.min(v);
            hi = hi.max(v);
        }
    }
    (lo.x <= hi.x).then_some((lo, hi))
}

/// The camera's view direction: from the south-east and above, like the
/// default city view.
fn view_dir() -> Vec3 {
    Vec3::new(0.75, 0.85, 1.0).normalize()
}

/// Spawn every thumbnail set once the assets are in; take the cameras
/// down after `THUMB_FRAMES` and publish the images.
#[allow(clippy::too_many_arguments)]
fn make_thumbs(
    mut commands: Commands,
    mut thumbs: ResMut<Thumbs>,
    mut images: ResMut<Assets<Image>>,
    mut meshes: ResMut<Assets<Mesh>>,
    mut std_mats: ResMut<Assets<StandardMaterial>>,
    mut egui_tex: ResMut<EguiUserTextures>,
    mats: Option<Res<Materials>>,
    assets: Res<GameAssets>,
) {
    if thumbs.started {
        if thumbs.temp.is_empty() {
            return;
        }
        thumbs.frames += 1;
        if thumbs.frames >= THUMB_FRAMES {
            for e in std::mem::take(&mut thumbs.temp) {
                commands.entity(e).despawn();
            }
            let pending = std::mem::take(&mut thumbs.pending);
            thumbs.ids.extend(pending);
        }
        return;
    }
    let Some(mats) = mats else { return };
    thumbs.started = true;
    let ground = std_mats.add(StandardMaterial { base_color: Color::linear_rgb(0.012, 0.014, 0.02), perceptual_roughness: 0.95, ..default() });
    let layer = RenderLayers::layer(LAYER);
    // The key light and a cool fill, on the thumbnail layer only.
    for (dir, lux) in [(Vec3::new(-0.6, -1.0, -0.4), 9_000.0), (Vec3::new(0.7, -0.4, 0.5), 2_500.0)] {
        let e = commands.spawn((DirectionalLight { illuminance: lux, shadow_maps_enabled: false, ..default() }, Transform::from_translation(ORIGIN).looking_to(dir, Vec3::Y), layer.clone())).id();
        thumbs.temp.push(e);
    }
    let all = crate::ui::build::all_placeables();
    for (i, p) in all.into_iter().enumerate() {
        let k = key(p);
        if thumbs.pending.contains_key(&k) {
            continue;
        }
        let Some(geo) = building(p, &assets.rules, &assets.palette) else { continue };
        let Some((lo, hi)) = bounds(&geo) else { continue };
        let at = ORIGIN + Vec3::new((i % 8) as f32 * 2_000.0, 0.0, (i / 8) as f32 * 2_000.0);
        for (s, data) in geo.iter() {
            if data.positions.is_empty() {
                continue;
            }
            let mesh = Mesh3d(meshes.add(to_mesh(data, !s.is_glow())));
            let mat = if s.is_glow() { mats.glow() } else { mats.surface(s) };
            let e = commands.spawn((mesh, MeshMaterial3d(mat), Transform::from_translation(at), layer.clone(), NotShadowCaster, NotShadowReceiver)).id();
            thumbs.temp.push(e);
        }
        // A dark pad under it so it does not float.
        let span = (hi - lo).max_element().max(10.0);
        let pad = commands.spawn((Mesh3d(meshes.add(Plane3d::default().mesh().size(span * 1.25, span * 1.25))), MeshMaterial3d(ground.clone()), Transform::from_translation(at + Vec3::new((lo.x + hi.x) * 0.5, lo.y.min(0.0) - 0.05, (lo.z + hi.z) * 0.5)), layer.clone())).id();
        thumbs.temp.push(pad);
        // Frame the bounding box from the view direction.
        let centre = at + (lo + hi) * 0.5;
        let dir = view_dir();
        let right = Vec3::Y.cross(dir).normalize();
        let up = dir.cross(right).normalize();
        let half = (hi - lo) * 0.5;
        let mut ext = Vec2::ZERO;
        for sx in [-1.0, 1.0] {
            for sy in [-1.0, 1.0] {
                for sz in [-1.0, 1.0] {
                    let c = Vec3::new(half.x * sx, half.y * sy, half.z * sz);
                    ext = ext.max(Vec2::new(c.dot(right).abs(), c.dot(up).abs()));
                }
            }
        }
        let size = ext.max_element() * 2.0 * 1.08 + 2.0;
        let image = images.add(Image::new_target_texture(SIZE, SIZE, TextureFormat::Rgba8UnormSrgb, None));
        let distance = span * 3.0 + 50.0;
        let cam = commands
            .spawn((
                Camera3d::default(),
                Camera { order: -20 - i as isize, clear_color: ClearColorConfig::Custom(Color::linear_rgb(0.012, 0.014, 0.024)), ..default() },
                RenderTarget::Image(image.clone().into()),
                Projection::Orthographic(OrthographicProjection { scaling_mode: ScalingMode::Fixed { width: size, height: size }, near: 0.0, far: distance * 2.0, ..OrthographicProjection::default_3d() }),
                Transform::from_translation(centre + dir * distance).looking_at(centre, Vec3::Y),
                layer.clone(),
            ))
            .id();
        thumbs.temp.push(cam);
        let id = egui_tex.add_image(EguiTextureHandle::Strong(image));
        thumbs.pending.insert(k, id);
    }
}

/// The built-up area: every lot and road node, or the middle of the map
/// when nothing is built. Returns (centre, side) of a square, metres.
fn city_square(w: &nd_sim::World) -> (SVec2, f32) {
    let mut lo = SVec2::splat(f32::MAX);
    let mut hi = SVec2::splat(f32::MIN);
    let mut any = false;
    for l in w.lots.values() {
        for p in &l.polygon {
            lo = lo.min(*p);
            hi = hi.max(*p);
            any = true;
        }
    }
    if !any {
        return (SVec2::ZERO, 1200.0);
    }
    let side = (hi - lo).max_element().max(400.0) * 1.12;
    ((lo + hi) * 0.5, side)
}

/// Run the save pictures: start a camera for each request, take its
/// picture after `SHOT_FRAMES`, then take the camera down.
fn save_shots(mut commands: Commands, mut shots: ResMut<SaveShots>, mut saves: ResMut<crate::ui::Saves>, mut images: ResMut<Assets<Image>>, sim: Res<Sim>) {
    for path in saves.take_shots() {
        // One picture per file at a time (autosaves at high speed come
        // faster than a picture takes).
        if shots.running.iter().any(|s| s.path == path) {
            continue;
        }
        let (c, side) = city_square(&sim.world);
        let image = images.add(Image::new_target_texture(SHOT_SIZE, SHOT_SIZE, TextureFormat::Rgba8UnormSrgb, None));
        let centre = Vec3::new(c.x, 0.0, c.y);
        let camera = commands
            .spawn((
                Camera3d::default(),
                Camera { order: -5, ..default() },
                RenderTarget::Image(image.clone().into()),
                Projection::Orthographic(OrthographicProjection { scaling_mode: ScalingMode::Fixed { width: side, height: side }, near: 0.0, far: 3_000.0, ..OrthographicProjection::default_3d() }),
                // Straight down, north (-z on screen, as the city view
                // starts) at the top.
                Transform::from_translation(centre + Vec3::Y * 1_200.0).looking_at(centre, Vec3::NEG_Z),
            ))
            .id();
        shots.running.push(Shot { path, camera, image, frames: 0 });
    }
    let mut done = Vec::new();
    for (i, shot) in shots.running.iter_mut().enumerate() {
        shot.frames += 1;
        if shot.frames == SHOT_FRAMES {
            commands.spawn(Screenshot::image(shot.image.clone())).observe(save_to_disk(shot.path.clone()));
        }
        // The capture is queued on the frame above; a few more frames for
        // the copy to land before the camera and its image go.
        if shot.frames >= SHOT_FRAMES + 10 {
            commands.entity(shot.camera).despawn();
            done.push(i);
        }
    }
    if !done.is_empty() {
        // The lists show the new picture.
        saves.mark_dirty();
    }
    for i in done.into_iter().rev() {
        shots.running.remove(i);
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn every_building_placeable_generates() {
        let (rules, palette) = (nd_procgen::BuildingRules::default(), nd_procgen::Palette::default());
        for p in crate::ui::build::all_placeables() {
            if matches!(p, Placeable::Toll(_)) {
                continue;
            }
            let g = building(p, &rules, &palette).expect("a building");
            assert!(bounds(&g).is_some(), "{p:?} drew nothing");
        }
    }
}
